import { mockExpiredResetToken, mockResetToken, mockUser } from '../mocks/fixtures.ts';
import { expect, test } from '../mocks/test.ts';

/*
 * AUTH-13: visual-regression coverage for the four public auth screens, which shipped with none.
 * 7 states x 3 breakpoints = 21 test instances, all *new* baselines — generated by the
 * `update-baselines` GitHub dispatch, never on a Windows host.
 *
 * No login is needed: every screen here is public. Triggers are copied from the passing functional
 * specs (password-reset.spec.ts, auth-errors.spec.ts) — same fixtures, same selectors — with a
 * screenshot at each checkpoint instead of a functional assertion.
 *
 *  - /login "Password updated" notice: reached the real way, by completing a reset with the one
 *    live token (the notice travels via accountNoticeStore, so it cannot be deep-linked).
 *  - /reset-password link problem: the mock validate endpoint answers 404 for every token but the
 *    live one, so `mockExpiredResetToken` lands on the link-problem state on page load (the used /
 *    unknown tokens render the same layout, differing only in one sentence).
 *
 * The community illustration floats continuously (cg-float) and inputs show a blinking caret, so
 * every shot disables CSS animations and blurs the active element first. Clock frozen at the same
 * instant as every other visual spec — none of this content is clock-sensitive.
 */

const FROZEN_TIME = new Date('2026-07-07T19:00:00');
const breakpoints = [375, 768, 1280] as const;

async function settle(page: import('@playwright/test').Page) {
  await page.evaluate('document.activeElement?.blur()');
  await page.evaluate('document.fonts.ready');
}

async function prepare(page: import('@playwright/test').Page, width: number) {
  await page.clock.setFixedTime(FROZEN_TIME);
  await page.setViewportSize({ width, height: 900 });
}

for (const width of breakpoints) {
  test(`login — default @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto('/login');
    await expect(page.getByRole('button', { name: 'Log in' })).toBeVisible();
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-login-default-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`login — password updated notice @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto(`/reset-password?token=${mockResetToken}`);
    await page.getByLabel('New password', { exact: true }).fill('newpassword1');
    await page.getByLabel('Confirm new password').fill('newpassword1');
    await page.getByRole('button', { name: 'Update password' }).click();
    await expect(page.getByRole('status')).toContainText('Password updated. Sign in with your new password.');
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-login-password-updated-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`register — default @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto('/register');
    await expect(page.getByRole('heading', { name: 'Create your account' })).toBeVisible();
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-register-default-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`forgot password — form @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto('/forgot-password');
    await expect(page.getByRole('heading', { name: 'Forgot your password?' })).toBeVisible();
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-forgot-password-form-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`forgot password — sent @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto('/forgot-password');
    await page.getByLabel('Email', { exact: true }).fill(mockUser.email);
    await page.getByRole('button', { name: 'Send reset link' }).click();
    await expect(page.getByRole('status')).toContainText('If an account exists for that email');
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-forgot-password-sent-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`reset password — form @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto(`/reset-password?token=${mockResetToken}`);
    await expect(page.getByRole('heading', { name: 'Choose a new password' })).toBeVisible();
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-reset-password-form-${width}.png`, { fullPage: true, animations: 'disabled' });
  });

  test(`reset password — link problem @ ${width}px`, async ({ page }) => {
    await prepare(page, width);
    await page.goto(`/reset-password?token=${mockExpiredResetToken}`);
    await expect(page.getByRole('heading', { name: 'This link can’t be used' })).toBeVisible();
    await settle(page);

    await expect(page).toHaveScreenshot(`auth-reset-password-link-problem-${width}.png`, { fullPage: true, animations: 'disabled' });
  });
}
